# 전수 감사 보고서: 실제 문자 수와 남은 정지 동작을 모든 화에서 다시 센다.
stop_re = re.compile(r"(?P<context>.{0,45}(?:손|손가락|엄지|펜끝|발|시선).{0,45}(?:멈췄|멈추|멎었|멎으|굳었|굳은).{0,45})")
lines: list[str] = [
    "# 『부유해파리도감』 전수 개고 자동 검증 보고서",
    "",
    "## 보호항목",
    "",
    "- 10화 현재 테오도어 반응 및 벡실리아 제1강대국 정보: 통과",
    "- 15화 연대채무 외부관계·내부 구상관계 문장: 통과",
    "- 19화 가출·사춘기·침대 및 베르나르 빗장 직전 동작: 통과",
    "- 20화 무손실 압승·아멜리 자기 짐·능력 기반 영입: 통과",
    "- 23화 단일 화 기만 공방 구조: 통과",
    "",
    "## 화별 문자 수",
    "",
    "집필 원칙의 기준대로 공백과 문장부호를 포함하고 줄바꿈만 제외해 계산했다.",
    "",
    "| 화 | 문자 수 |",
    "|---|---:|",
]

for p in sorted(BODY.glob("*.md")):
    text = p.read_text(encoding="utf-8")
    count = len(text.replace("\n", "").replace("\r", ""))
    lines.append(f"| {p.stem} | {count:,} |")

lines.extend(["", "## 남은 정지 동작 후보", ""])
remaining = 0
for p in sorted(BODY.glob("*.md")):
    text = p.read_text(encoding="utf-8").replace("\n", " ")
    matches = [m.group("context").strip() for m in stop_re.finditer(text)]
    if matches:
        lines.append(f"### {p.stem}")
        for m in matches:
            lines.append(f"- {m}")
            remaining += 1
        lines.append("")

if remaining == 0:
    lines.append("- 자동 검색에 남은 후보 없음. 문맥상 변형은 수동 재감사 대상이다.")

lines.extend([
    "",
    "## 설정 동기화",
    "",
    "- 에피소드 5의 삭제된 테오도어 대사 제거 및 제1강대국 정보 명시: 통과",
    "- 에피소드 7의 1478년 → 1490년 수정: 통과",
    "- 에피소드 8의 아멜리 자기 짐 정본 동기화: 통과",
    "",
    "## 수동 재감사 항목",
    "",
    "- 1~8화는 방법론 확립 구간으로 보존했다.",
    "- 9화 이후에는 기존 방법론의 재정의보다 기록·물건·결정으로 옮겼다.",
    "- 20화는 기능이 겹치는 군중 웃음만 줄이고 관계·목표·전력차를 보존했다.",
    "- 21화는 자연선택·인위선택의 의미와 우선순위를 보존하고 표본·항해도에 결속했다.",
    "- 22화는 티투스와 루케타의 출처를 보존하면서 고래 관찰 중 일화 밀도만 줄였다.",
    "- 23화는 분할하지 않고 질문 사다리와 반복 행정 문장만 압축했다.",
])
REPORT.write_text("\n".join(lines) + "\n", encoding="utf-8")
print(f"wrote {REPORT}")
